class Solution:
    def smallestString(self, s: str) -> str:
        s = list(s)
        i = 0
        # Find the first non 'a' character
        while i < len(s) and s[i] == 'a':
            i += 1
        # If all characters are 'a', replace all with 'z'
        if i == len(s):
            for j in range(len(s)):
                s[j] = 'z'
        else:
            # Process from i to the end until 'a' is encountered
            for j in range(i, len(s)):
                if s[j] == 'a':
                    break
                s[j] = chr(ord(s[j]) - 1)
        return ''.join(s)
```

